import{_ as s,C as e,o as i,c as l,j as a,a as h,E as r,a2 as d}from"./chunks/framework.B-bxTAy7.js";const P=JSON.parse('{"title":"内容状态与成熟度","description":"由构建脚本扫描正文自动生成的内容清单：每节字数、例题数、演示数，以及成熟度判定标准。","frontmatter":{"title":"内容状态与成熟度","description":"由构建脚本扫描正文自动生成的内容清单：每节字数、例题数、演示数，以及成熟度判定标准。","outline":[2]},"headers":[],"relativePath":"guide/status.md","filePath":"guide/status.md","lastUpdated":1792416913000}'),g={name:"guide/status.md"};function c(_,t,p,u,b,m){const o=e("Meta"),n=e("StatusTable");return i(),l("div",null,[t[0]||(t[0]=a("h1",{id:"内容状态与成熟度",tabindex:"-1"},[h("内容状态与成熟度 "),a("a",{class:"header-anchor",href:"#内容状态与成熟度","aria-label":'Permalink to "内容状态与成熟度"'},"​")],-1)),r(o,{time:"3 min",level:"指南",note:"这张表由脚本扫描正文生成，不是手写的进度条"}),t[1]||(t[1]=d('<h2 id="为什么有这一页" tabindex="-1">为什么有这一页 <a class="header-anchor" href="#为什么有这一页" aria-label="Permalink to &quot;为什么有这一页&quot;">​</a></h2><p>一个学习站最容易骗人的地方是「看起来什么都有」。所以这一页不写「已全部完成」，而是把每节的实际内容量摊开：<strong>多少字、几道例题、几个演示、有没有易错清单</strong>。数字从 Markdown 源文件里数出来，每次构建都会重算。</p><h2 id="判定标准" tabindex="-1">判定标准 <a class="header-anchor" href="#判定标准" aria-label="Permalink to &quot;判定标准&quot;">​</a></h2><table tabindex="0"><thead><tr><th>列</th><th>含义</th></tr></thead><tbody><tr><td>字数</td><td>去掉代码块与 HTML 标签后的正文非空白字符数</td></tr><tr><td>例题</td><td>形如 <code>::: tip 例 N · …</code> 的例题块数量</td></tr><tr><td>演示 / 图</td><td><code>&lt;DemoBox&gt;</code> 与 <code>&lt;FigBox&gt;</code> 的个数</td></tr><tr><td>结 / 错 / 工</td><td>是否含「结论先行」「易错点」「工程实例」三个模块</td></tr><tr><td>成熟度</td><td><strong>完整</strong>：≥3000 字且 ≥4 道例题；<strong>够用</strong>：≥1800 字且 ≥2 道；<strong>偏薄</strong>：其余</td></tr></tbody></table><p>「偏薄」不代表内容错，只代表它目前更像<strong>提纲</strong>：够用来复习结论，不够用来第一次学。</p><h2 id="计划扩写的两处偏薄章节" tabindex="-1">计划扩写的两处偏薄章节 <a class="header-anchor" href="#计划扩写的两处偏薄章节" aria-label="Permalink to &quot;计划扩写的两处偏薄章节&quot;">​</a></h2><p>下表由脚本生成，会随内容变化自动更新。这里单列两处已知的「偏薄」章节，因为它们的页面标签（🔴 核心）与实际内容量存在冲突——<strong>标签说必读，内容却更像提纲</strong>。</p><table tabindex="0"><thead><tr><th>章节</th><th>现状</th><th>处置</th><th>计划</th></tr></thead><tbody><tr><td><a href="./../analog/frequency">模拟电子 · 03 放大电路的频率响应</a></td><td>约 1600 字，4 道例题，标「核心」</td><td><strong>计划扩写</strong></td><td>补「图解」与「工程实例」两段：把波特图的渐近近似与真实 −3 dB 曲线并排画出，补一段「多级级联的带宽收缩」与阻容取值对下限频率的影响；目标 3000 字以上，扩写后标签维持「核心」</td></tr><tr><td><a href="./../embedded/timer-pwm">嵌入式 · 07 定时器与 PWM</a></td><td>约 1250 字，4 道例题，标「核心」</td><td><strong>计划扩写</strong></td><td>补「图解」与「工程实例」两段：补定时器与 PWM 的时序图示、补输入捕获测频的完整代码与误差预算、补 PWM 驱动电机/舵机的参数选择表；目标 3000 字以上，扩写后标签维持「核心」</td></tr></tbody></table><p><strong>为什么是「计划扩写」而不是降级</strong>：频率响应是模电「增益带宽积」这条主线的承重章，定时器与 PWM 是嵌入式「时间基准」这条主线的承重章，两处都是后续章节反复回引的概念。降成「了解」会让主线断掉；把字数补到「完整」线以下再改标签，是更诚实的做法。</p><p><strong>这两处的判定由脚本给出，不是手写的</strong>：扩写后字数与例题数变化会直接反映到下面这张表里，标签与判据的冲突随之消失。</p><h2 id="全站内容清单" tabindex="-1">全站内容清单 <a class="header-anchor" href="#全站内容清单" aria-label="Permalink to &quot;全站内容清单&quot;">​</a></h2>',11)),r(n),t[2]||(t[2]=d('<p>分课程的同一张表：<a href="./../ee/depth">电工学</a> · <a href="./../embedded/depth">嵌入式开发</a>。</p><h2 id="怎么用这张表" tabindex="-1">怎么用这张表 <a class="header-anchor" href="#怎么用这张表" aria-label="Permalink to &quot;怎么用这张表&quot;">​</a></h2><ul><li><strong>第一次学</strong>：优先挑「完整」的章节精读；「偏薄」的先看别的资料，或用本站的结论 + 速查表兜底。</li><li><strong>复习</strong>：三列全绿的章节可以只扫「结论先行」和「易错点」。</li><li><strong>想参与</strong>：从「偏薄」且你正好在学的章节开始补，比从头写新章更有价值——见<a href="./contributing">写作与贡献指南</a>。</li></ul>',3))])}const T=s(g,[["render",c]]);export{P as __pageData,T as default};
